INSERT INTO product_lines
  (id, name, thickness_mil, material, weave_count, weight_oz_per_sqyd, grommet_type, grommet_spacing_inches,
   uv_resistant, waterproof, mildew_resistant, fire_retardant, reinforced_corners, sewn_in_rope, description)
VALUES
  ('5mil-light', '5-Mil Light Duty Poly', 5, 'Polyethylene', '10x10', 1.5, 'Aluminum', 18,
   true, true, true, false, false, false, 'Lightweight and affordable for temporary use. Great for camping ground cloths, home projects, furniture covers, and general outdoor use.'),
  ('7mil-standard', '7-Mil Standard Duty Poly', 7, 'Polyethylene', '12x12', 2.0, 'Aluminum', 18,
   true, true, true, false, false, false, 'Balanced durability for general outdoor use. Works from -50F to 180F. Good for equipment covers, truck bed liners, and construction ground protection.'),
  ('10mil-heavy', '10-Mil Heavy Duty Poly', 10, 'Polyethylene', '12x12', 2.5, 'Aluminum', 18,
   true, true, true, false, true, false, 'Heavy-duty poly for demanding applications. Reinforced corners for extra durability. Ideal for construction sites, debris covers, and outdoor storage.'),
  ('12mil-xheavy', '12-Mil Extra Heavy Duty Poly', 12, 'Polyethylene', '14x14', 3.0, 'Aluminum', 18,
   true, true, true, false, true, true, 'Extra heavy-duty with sewn-in rope perimeter for maximum strength. Built for roofing projects, scaffold enclosures, and heavy outdoor use.'),
  ('16mil-super', '16-Mil Super Heavy Duty Poly', 16, 'Polyethylene', '14x14', 4.0, 'Aluminum', 18,
   true, true, true, false, true, true, 'Industrial-grade super heavy-duty poly. Used by contractors and farmers for long-term outdoor applications and permanent storage structures.'),
  ('20mil-ultra', '20-Mil Ultra Heavy Duty Poly', 20, 'Polyethylene', '16x16', 5.0, 'Aluminum', 18,
   true, true, true, false, true, true, 'The toughest poly tarp in our lineup. 20-mil thickness for permanent commercial outdoor covers, extreme weather, and years of continuous use.'),
  ('fr-poly', 'Fire Retardant Poly Tarp', 16, 'Fire Retardant Polyethylene', '14x14', 4.0, 'Aluminum', 18,
   true, true, true, true, true, false, 'NFPA 701 rated fire retardant. Self-extinguishing when flame is removed. Required for welding areas, electrical work, and OSHA-regulated job sites.'),
  ('canvas-standard', 'Heavy Cotton Canvas Tarp', NULL, 'Cotton Canvas', NULL, 18.0, 'Brass', 24,
   false, false, false, false, true, false, 'Traditional breathable cotton canvas. Used for painting drop cloths, vehicle and antique equipment covers, and applications where air circulation matters.');

